/* Archivo styles.css */
selector {
  propiedad: valor;
}

/* Inline */
<p style="color: red;">Texto rojo</p>

/* Interno */
<style>
  p { color: blue; }
</style>

/* ===== Reset básico ===== */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* ===== Tipografía ===== */
body {
  font-family: system-ui, sans-serif;
  line-height: 1.5;
}

/* ===== Componentes ===== */
.btn {
  padding: 8px 16px;
  border-radius: 6px;
}

.btn:hover {
  background-color: #7c3aed;
  color: #fff;
}

/* La herencia: algunas propiedades pasan de padre a hijo */
body {
  color: #333;          /* se hereda a todos los elementos */
  font-family: Arial;   /* se hereda */
  font-size: 16px;      /* se hereda */
}

/* La cascada: gana el más específico o el último */
p {
  color: red;
}

p.destacado {
  color: blue;          /* más específico: gana */
}

/* El orden también importa si hay igual especificidad */
p {
  color: red;
}

p {
  color: green;         /* último: gana */
}

/* Selector de etiqueta */
p { font-size: 16px; }

/* Selector de clase */
.destacado { background: yellow; }

/* Selector de id */
#logo { width: 200px; }

/* Descendiente: cualquier ul dentro de nav */
nav ul {
  list-style: none;
}

/* Hijo directo (>) */
nav > ul {
  padding: 0;
}

/* Selector de atributo */
a[target="_blank"] {
  color: purple;
}

input[type="email"] {
  border: 2px solid #7c3aed;
}

/* Agrupar selectores con coma */
h1, h2, h3 {
  font-weight: 600;
}

/* Clases combinadas en el HTML */
.alert {
  padding: 12px;
  border-radius: 6px;
}

.alert.success {
  background-color: #d4edda;
  color: #155724;
}

.alert.error {
  background-color: #f8d7da;
  color: #721c24;
}

/* HTML: <div class="alert error">Error</div> */

/* Hermano adyacente (+): el p inmediatamente después de un h2 */
h2 + p {
  margin-top: 0;
  font-weight: bold;
}

/* Hermanos generales (~): todos los span que siguen al h2 */
h2 ~ span {
  color: gray;
}

/* Ejemplo de HTML
<h2>Título</h2>
<p>Párrafo adyacente: sí seleccionado</p>
<span>Hermano general: sí seleccionado</span>
<div>Intermedio</div>
<span>Otro hermano: sí seleccionado</span> */

body {
  color: #333;
  background-color: #f5f5f5;
  font-family: 'Arial', sans-serif;
  font-size: 16px;
}

h1 {
  font-size: 2em;
  font-weight: bold;
}

p {
  text-align: justify;       /* alineación */
  text-transform: uppercase; /* mayúsculas/minúsculas */
  letter-spacing: 1px;       /* espaciado entre letras */
  line-height: 1.6;          /* alto de línea */
  text-decoration: underline;
  word-spacing: 3px;
}

.titulo {
  text-align: center;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.card {
  background-color: #fff;
  background-image: url("fondo.png");
  background-repeat: no-repeat;
  background-size: cover;
  background-position: center;
}

.banner {
  background: linear-gradient(90deg, #7c3aed, #4f46e5);
  color: #fff;
}

.radial {
  background: radial-gradient(circle, #fff, #7c3aed);
}

div {
  width: 300px;
  padding: 20px;
  border: 2px solid black;
  margin: 10px;
  box-sizing: border-box;
}

.caja {
  /* Atajo: arriba derecha abajo izquierda */
  padding: 10px 20px 30px 40px;
  /* = padding-top: 10px;
     padding-right: 20px;
     padding-bottom: 30px;
     padding-left: 40px; */
}

.centrado {
  /* Atajo: vertical horizontal */
  margin: 20px auto;
  /* auto centra horizontalmente si hay ancho definido */
  width: 300px;
}

.elemento {
  width: 100px;
  height: 50px;
  padding: 10px;
  border: 2px solid #333;
  /* Tamaño total = width + padding + border */
}

/* Por defecto: el width NO incluye padding ni borde */
.content-box {
  width: 300px;
  padding: 20px;
  border: 5px solid black;
  /* Ancho total real: 300 + 20 + 20 + 5 + 5 = 350px */
}

/* Recomendado: el width sí los incluye */
.border-box {
  width: 300px;
  padding: 20px;
  border: 5px solid black;
  box-sizing: border-box;
  /* Ancho total real: 300px */
}

/* Aplicar globalmente con el reset */
* {
  box-sizing: border-box;
}

/* Los márgenes verticales de elementos adyacentes se fusionan */
h1 {
  margin-bottom: 40px;
}

h2 {
  margin-top: 40px;
}

/* La separación real será 40px, NO 80px: los márgenes colapsan */

/* El colapso también ocurre entre padre e hijo */
.padre {
  margin-top: 20px;
}

.padre .hijo {
  margin-top: 30px;
}
/* Resultado: 30px (el mayor), no 50px */

/* Soluciones: usar flexbox/grid o margin en un solo lado */
.tarjetas {
  display: flex;
  gap: 20px;
}

.bloque { display: block; }
.enlinea { display: inline; }
.flex { display: flex; }

.relativo { position: relative; top: 10px; }
.absoluto { position: absolute; top: 0; right: 0; }
.fijo { position: fixed; bottom: 0; }

.en-linea {
  display: inline;   /* ocupa solo su contenido */
}

.en-linea-bloque {
  display: inline-block;  /* acepta width/height pero fluye en línea */
  width: 120px;
  height: 50px;
}

.oculto {
  display: none;      /* desaparece y no ocupa espacio */
}

.invisible {
  visibility: hidden; /* ocupa espacio pero no se ve */
}

.flex {
  display: flex;      /* activa Flexbox en el contenedor */
}

.contenedor {
  position: relative;   /* punto de referencia para los hijos */
  border: 1px solid #ccc;
}

.icono-cerrar {
  position: absolute;
  top: 8px;
  right: 8px;
}

.badge {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}

/* El absolute se posiciona respecto al ancestro
   posicionado más cercano (el que tiene position). */

.navbar {
  position: fixed;    /* se mantiene fija al hacer scroll */
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
}

.titulo-pegajoso {
  position: sticky;   /* se queda pegada al llegar a su límite */
  top: 20px;
  background: #fff;
}

/* Diferencias:
   - fixed: siempre relativa al viewport.
   - sticky: relativa a su contenedor, se pega al hacer scroll. */
/* Los elementos posicionados aceptan z-index */

a:hover { color: red; }
li:nth-child(odd) { background: #eee; }

p::before { content: '⚠️ '; }
p::after { content: ' ✅'; }

input:focus {
  border-color: #7c3aed;
  outline: 2px solid rgba(124, 58, 237, 0.3);
}

input:required {
  border-left: 4px solid orange;
}

input:disabled {
  background-color: #e5e7eb;
  cursor: not-allowed;
}

input:checked + label {
  font-weight: bold;
}

input:valid {
  border-color: green;
}

.boton {
  background: #7c3aed;
  color: #fff;
  padding: 8px 16px;
  border: none;
}

.boton::before {
  content: '→ ';
}

.boton::after {
  content: '';
  display: inline-block;
  width: 8px;
  height: 8px;
  background: #fff;
  margin-left: 6px;
}

.cita::first-letter {
  font-size: 2em;
  color: #7c3aed;
}

/* Primer hijo de su padre */
li:first-child {
  font-weight: bold;
}

/* Último hijo */
li:last-child {
  border: none;
}

/* Patrones: 2n = pares, 3n+1 = posiciones 1, 4, 7... */
li:nth-child(2n) {
  background-color: #f3f4f6;
}

li:nth-child(3n+1) {
  color: #7c3aed;
}

/* Un elemento específico */
li:nth-child(4) {
  font-style: italic;
}

p {
  font-size: 1.2rem;   /* relativa al root */
  margin-bottom: 1em; /* relativa al font-size del elemento */
  width: 50%;         /* relativa al contenedor */
  height: 100vh;      /* viewport height */
}

/* px: fijo, no se adapta */
p { font-size: 16px; }

/* em: relativa al font-size del elemento padre */
.contenedor { font-size: 20px; }
.contenedor p { font-size: 2em; }   /* = 40px */

/* rem: relativa al font-size de <html> */
html { font-size: 16px; }
h1 { font-size: 2rem; }             /* = 32px siempre */

/* em se compone al anidar: problema clásico */
.caja { font-size: 1.5em; }        /* 24px si el padre es 16px */
.caja .caja { font-size: 1.5em; }  /* 36px, se multiplica */

/* Porcentajes: relativos al contenedor */
.container {
  width: 80%;
  max-width: 1200px;
  margin: 0 auto;
}

.hijo {
  width: 50%;    /* la mitad del contenedor */
}

/* Unidades de viewport */
.hero {
  height: 100vh;    /* 100% de la altura de la pantalla */
  width: 100vw;     /* 100% del ancho de la pantalla */
}

.mitad-altura {
  height: 50vh;
}

/* vmin/vmax */
.cuadrado {
  width: 50vmin;    /* menor entre ancho y alto del viewport */
}

/* calc(): combinar unidades con operaciones */
.sidebar {
  width: calc(100% - 240px);
}

.encabezado {
  padding: calc(1rem + 10px);
}

/* clamp(): tamaño fluido entre un mínimo y un máximo */
.titulo {
  font-size: clamp(1rem, 2.5vw, 3rem);
}
/* En pantallas pequeñas: 1rem; grandes: 3rem;
   en el medio: 2.5vw */

/* Uso combinado */
.card {
  width: clamp(280px, 50%, 600px);
}

/* Mobile first: estilos base pensados para móvil */
.tarjeta {
  display: block;
  padding: 16px;
  font-size: 16px;
}

/* Mejoras progresivas para pantallas más grandes */
@media (min-width: 768px) {
  .tarjeta {
    display: flex;
    gap: 16px;
  }
}

@media (min-width: 1200px) {
  .tarjeta {
    max-width: 1100px;
    margin: 0 auto;
  }
}

/* Las imágenes no deben desbordar la pantalla */
img {
  max-width: 100%;
  height: auto;
}

video, iframe {
  max-width: 100%;
}

/* Contenedor fluido */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 16px;
}

/* Tipografía fluida */
body {
  font-size: clamp(1rem, 1.5vw, 1.25rem);
}

/* Breakpoints más comunes */
@media (max-width: 576px)  { /* teléfonos pequeños */ }
@media (min-width: 768px)  { /* tablets en adelante */ }
@media (min-width: 992px)  { /* escritorio */ }
@media (min-width: 1200px) { /* pantallas grandes */ }

/* Según la orientación del dispositivo */
@media (orientation: landscape) {
  body { flex-direction: row; }
}

/* Según la preferencia de tema del usuario */
@media (prefers-color-scheme: dark) {
  body {
    background-color: #111;
    color: #eee;
  }
}

.contenedor {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.contenedor {
  display: flex;
  justify-content: center;  /* eje principal (horizontal) */
  align-items: center;      /* eje cruzado (vertical) */
  height: 300px;
}

.contenedor-column {
  display: flex;
  flex-direction: column;   /* eje principal pasa a vertical */
  justify-content: space-evenly;
}

/* Con column:
   justify-content controla la vertical
   align-items controla la horizontal */
.item {
  width: 80px;
  height: 80px;
}

.contenedor {
  display: flex;
}

.item {
  flex-grow: 1;    /* reparte el espacio extra */
}

.item-doble {
  flex-grow: 2;    /* recibe el doble de espacio extra */
}

.item-fijo {
  flex-grow: 0;
  flex-shrink: 0;
  flex-basis: 150px;   /* tamaño base */
}

/* Atajo común */
.item-flex {
  flex: 1 1 0;   /* grow shrink basis */
}

.contenedor {
  display: flex;
  justify-content: space-between;
  align-items: center;      /* valor base para todos */
}

/* Alinear un solo item distinto al resto */
.item-especial {
  align-self: flex-end;
}

/* Reordenar visualmente sin tocar el HTML */
.item-ultimo { order: 10; }
.item-normal  { order: 0; }
.item-primero { order: -1; }   /* va antes que el resto */

/* flex-wrap: pasar a la siguiente línea */
.contenedor {
  display: flex;
  flex-wrap: wrap;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: auto;
  gap: 20px;
}

.item {
  grid-column: span 2;
}

.layout {
  display: grid;
  grid-template-columns: 1fr 3fr;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "header  header"
    "sidebar content"
    "footer  footer";
  gap: 10px;
  height: 100vh;
}

.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.content { grid-area: content; }
.footer  { grid-area: footer; }

/* HTML:
<div class="layout">
  <header class="header">...</header>
  <aside class="sidebar">...</aside>
  <main class="content">...</main>
  <footer class="footer">...</footer>
</div> */

/* fr: fracción del espacio disponible */
.grid-tres {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
}

/* minmax: mínimo y máximo flexibles */
.grid-responsive {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

/* repeat: repetir patrón */
.grid-paginado {
  display: grid;
  grid-template-columns: repeat(4, 100px);
}

/* auto-fill vs auto-fit:
   auto-fill crea columnas aunque no haya contenido
   auto-fit estira las que existen para llenar */

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.destacado {
  grid-column: 1 / 3;    /* de la columna 1 a la 3 */
  grid-row: 1 / 2;
}

.span-2 {
  grid-column: span 2;   /* ocupa 2 columnas desde donde está */
}

.centrado {
  grid-column: 2 / 4;    /* centrar entre columnas 2 y 3 */
  grid-row: 2 / 3;
}

/* Sin el grid, el flujo llena celdas automáticamente */

.tarjeta {
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
  background: linear-gradient(135deg, #667eea, #764ba2);
  opacity: 0.9;
  transition: transform 0.3s ease;
}
.tarjeta:hover {
  transform: scale(1.05);
}

.mover {
  transform: translate(10px, 20px);  /* desplazar */
}

.rotar {
  transform: rotate(45deg);
}

.escalar {
  transform: scale(1.2);   /* agrandar 20% */
}

.inclinar {
  transform: skew(10deg);
}

/* Combinar varias transformaciones en orden */
.multiple {
  transform: translate(10px, 20px) rotate(45deg) scale(1.1);
}

/* Con transform-origin cambia el punto de rotación */
.rotar-esquina {
  transform: rotate(45deg);
  transform-origin: top left;
}

.boton {
  background-color: #7c3aed;
  color: #fff;
  transition:
    background-color 0.3s ease,
    transform 0.3s ease;
}

.boton:hover {
  background-color: #5b21b6;
  transform: translateY(-2px);
}

/* Atajo con todos los valores */
.card {
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Propiedades animables */
.elemento {
  transition: opacity 0.5s;
  opacity: 0;
}
.elemento.visible {
  opacity: 1;
}

@keyframes aparecer {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

.animado {
  animation: aparecer 0.8s ease-out forwards;
}

/* Animación con varios pasos */
@keyframes pulsar {
  0%   { transform: scale(1); }
  50%  { transform: scale(1.1); }
  100% { transform: scale(1); }
}

.pulso {
  animation: pulsar 1.5s infinite;
}

/* Atajo: nombre duración easing delay iteración */
.logo {
  animation: aparecer 1s ease-in 0.2s 1 both;
}

// Esto es un comentario
console.log('Hola, JavaScript');

let nombre = 'Ana';
const edad = 25;
var activo = true;

// const: no puede reasignarse
const nombre = 'Ana';
// nombre = 'Luis';  // Error

// let: sí puede reasignarse
let edad = 25;
edad = 26;

// var: ámbito de función (evitar)
var activo = true;

// Ámbito de bloque con let/const
{
  let temporal = 'solo aquí';
}
// console.log(temporal);  // ReferenceError

// Convención: camelCase
let precioTotal = 100;
const NOMBRE_MAXIMO = 10;  // constantes en mayúsculas

// Conversión a número
Number('42');       // 42
parseInt('42px');   // 42
parseFloat('3.14'); // 3.14

// Conversión a texto
String(42);         // '42'
(42).toString();    // '42'

// Conversión a booleano
Boolean(0);         // false
Boolean('');        // false
Boolean('Hola');    // true

// Coerción automática (cuidado)
console.log('5' + 3);   // '53'  (concatena)
console.log('5' - 3);   // 2     (resta)

// Valores falsy
if (!0 || !'' || !null || !undefined || !NaN || !false) {
  console.log('Todos son falsy');
}

const nombre = 'Ana';
const edad = 25;

// Concatenación clásica
console.log('Hola, ' + nombre + ', tienes ' + edad + ' años.');

// Template literal con backticks
console.log(`Hola, ${nombre}, tienes ${edad} años.`);

// Expresiones dentro de las llaves
console.log(`El doble de tu edad es ${edad * 2}`);

// Multilínea sin \n
const mensaje = `
  Línea 1
  Línea 2
`;
console.log(mensaje);

let hora = 10;
if (hora < 12) {
  console.log('Buenos días');
} else if (hora < 18) {
  console.log('Buenas tardes');
} else {
  console.log('Buenas noches');
}

let dia = 'lunes';
switch (dia) {
  case 'lunes':
    console.log('Inicio de semana');
    break;
  default:
    console.log('Otro día');
}

// Comparación estricta vs flexible
5 === '5'   // false (tipos distintos)
5 == '5'    // true  (coerción) - evítalo
5 !== 4     // true

// Operadores lógicos
const esMayor = true;
const esAdulto = false;

esMayor && esAdulto   // false (y)
esMayor || esAdulto   // true  (o)
!esMayor              // false (no)

// Comparar con estricto siempre
const usuario = { edad: 18 };
if (usuario.edad === 18) {
  console.log('Tiene exactamente 18');
}

const edad = 18;

// if/else
let mensaje;
if (edad >= 18) {
  mensaje = 'Mayor de edad';
} else {
  mensaje = 'Menor de edad';
}

// Ternario equivalente
const mensaje2 = edad >= 18 ? 'Mayor de edad' : 'Menor de edad';

// Ternario dentro de plantillas
console.log(`Eres ${edad >= 18 ? 'mayor' : 'menor'} de edad`);

// Ternarios encadenados (usar con cuidado)
const categoria =
  edad < 12 ? 'niño' :
  edad < 18 ? 'adolescente' :
  'adulto';

// Corto-circuito con ||: primer valor "verdadero"
const usuario = { nombre: '' };
const nombre = usuario.nombre || 'Invitado';
// 'Invitado' porque '' es falsy

// Nullish coalescing (??): solo null/undefined
const stock = 0;
const cantidad = stock ?? 10;   // 0 (0 NO es null/undefined)

// Encadenamiento opcional (?.)
const ciudad = usuario?.direccion?.ciudad;
// undefined si algo de la cadena no existe

// Asignación lógica
let valor = null;
valor ||= 18;      // valor = 18

// Combinado
const total = usuario?.carrito?.length ?? 0;

for (let i = 0; i < 5; i++) {
  console.log(i);
}

let j = 0;
while (j < 5) {
  console.log(j);
  j++;
}

const frutas = ['manzana', 'plátano', 'uva'];

// for...of: recorre los VALORES
for (const fruta of frutas) {
  console.log(fruta);   // 'manzana', 'plátano', 'uva'
}

const persona = { nombre: 'Ana', edad: 25 };

// for...in: recorre las CLAVES (objetos)
for (const clave in persona) {
  console.log(clave, persona[clave]);
}

// for...of también sirve con strings
for (const letra of 'hola') {
  console.log(letra);
}

// continue: salta la iteración actual
for (let i = 1; i <= 5; i++) {
  if (i === 3) continue;
  console.log(i);   // 1, 2, 4, 5
}

// break: termina el bucle por completo
let total = 0;
while (true) {
  total++;
  if (total >= 10) break;
}
console.log(total);   // 10

// break en un array con for...of
const numeros = [1, 2, 3, 4, 5];
for (const n of numeros) {
  if (n === 3) break;
  console.log(n);   // 1, 2
}

// do...while: se ejecuta al menos una vez
let i = 0;
do {
  console.log(i);
  i++;
} while (i < 3);    // 0, 1, 2

// Recorrer un array desde el final
const numeros = [1, 2, 3, 4, 5];
for (let j = numeros.length - 1; j >= 0; j--) {
  console.log(numeros[j]);   // 5, 4, 3, 2, 1
}

// Bucle con pasos personalizados
for (let k = 0; k <= 100; k += 10) {
  console.log(k);   // 0, 10, 20, ... 100
}

const texto = 'Hola mundo, bienvenidos';

// Búsqueda
texto.indexOf('mundo');         // 5 (posición o -1)
texto.includes('bienvenidos');  // true
texto.startsWith('Hola');       // true
texto.endsWith('.');            // false

// Extraer partes
texto.slice(5, 10);      // 'mundo'
