// Una promesa representa un valor futuro
const promesa = new Promise((resolve, reject) => {
  const exito = true;

  setTimeout(() => {
    if (exito) {
      resolve('Operación completada');
    } else {
      reject(new Error('Algo falló'));
    }
  }, 1000);
});

// Consumir la promesa
promesa
  .then((resultado) => {
    console.log('Éxito:', resultado);
  })
  .catch((error) => {
    console.error('Error:', error.message);
  })
  .finally(() => {
    console.log('Termina siempre');
  });

// Estado de una promesa:
//  pending (pendiente) -> fulfilled (cumplida)
//  pending -> rejected (rechazada)

// Simular un retraso con utilidad
const esperar = (ms) => new Promise((resolve) => {
  setTimeout(resolve, ms);
});
await esperar(500);

// Promise.all: espera TODAS (paralelo)
const traerUsuario = fetch('/api/usuarios/1').then(r => r.json());
const traerPosts = fetch('/api/usuarios/1/posts').then(r => r.json());

Promise.all([traerUsuario, traerPosts])
  .then(([usuario, posts]) => {
    console.log(usuario, posts);
  })
  .catch((error) => {
    console.error('Una falló:', error);
  });

// Promise.allSettled: no corta si una falla
Promise.allSettled([Promise.resolve(1), Promise.reject('x')])
  .then(resultados => {
    // [{status:'fulfilled',value:1},{status:'rejected',reason:'x'}]
    console.log(resultados);
  });

// Promise.race: la PRIMERA en completarse
const lento = new Promise(r => setTimeout(() => r('lento'), 2000));
const rapido = new Promise(r => setTimeout(() => r('rápido'), 100));

Promise.race([lento, rapido]).then(v => console.log(v));  // 'rápido'

// async convierte la función en una que devuelve promesa
async function cargarDatos() {
  try {
    // await pausa hasta que la promesa se resuelva
    const respuesta = await fetch('https://api.ejemplo.com/api/usuarios');

    if (!respuesta.ok) {
      throw new Error('Error HTTP: ' + respuesta.status);
    }

    const usuarios = await respuesta.json();
    return usuarios;
  } catch (error) {
    console.error('No se pudo cargar:', error.message);
    return [];
  }
}

// Uso
const usuarios = await cargarDatos();
console.log(usuarios);

