import { useEffect, useState } from 'react';

function Temporizador() {
  const [segundos, setSegundos] = useState(0);

  // Se ejecuta después de cada render
  useEffect(() => {
    console.log('El componente se renderizó');
  });

  // Con dependencias []: solo al montar
  useEffect(() => {
    console.log('Componente montado');
  }, []);

  // Con dependencia [segundos]: solo cuando cambia
  useEffect(() => {
    console.log('Segundos cambió a', segundos);
  }, [segundos]);

  // Limpieza: se ejecuta al desmontar o antes del siguiente efecto
  useEffect(() => {
    const intervalo = setInterval(() => {
      setSegundos((s) => s + 1);
    }, 1000);

    return () => clearInterval(intervalo);  // limpieza
  }, []);

  return <p>Tiempo: {segundos}s</p>;
}

import { useEffect, useState } from 'react';

function Usuarios() {
  const [usuarios, setUsuarios] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // fetch no puede ir directo en el efecto;
    // se declara una función async dentro
    const cargarUsuarios = async () => {
      try {
        const res = await fetch('/api/usuarios');
        if (!res.ok) throw new Error('Error al cargar');
        const data = await res.json();
        setUsuarios(data);
      } catch (e) {
        setError(e.message);
      } finally {
        setCargando(false);
      }
    };

    cargarUsuarios();
  }, []);   // [] = solo al montar

  if (cargando) return <p>Cargando...</p>;
  if (error) return <p>Error: {error}</p>;

  return (
    <ul>
      {usuarios.map((u) => <li key={u.id}>{u.nombre}</li>)}
    </ul>
  );
}

import { useEffect, useState } from 'react';

function Buscador({ busqueda }) {
  const [resultados, setResultados] = useState([]);

  useEffect(() => {
    // Se cancela la petición si la búsqueda cambia rápido
    const controlador = new AbortController();

    const buscar = async () => {
      try {
        const res = await fetch(
          '/api/buscar?q=' + busqueda,
          { signal: controlador.signal }
        );
        setResultados(await res.json());
      } catch (e) {
        if (e.name !== 'AbortError') console.error(e);
      }
    };

    buscar();

    // Limpieza: aborta la petición anterior
    return () => controlador.abort();
  }, [busqueda]);   // se re-ejecuta cuando cambia busqueda

  return (
    <ul>
      {resultados.map((r) => <li key={r.id}>{r.titulo}</li>)}
    </ul>
  );
}

