import { useState } from 'react';

function FormularioValidado() {
  const [datos, setDatos] = useState({ email: '', password: '' });
  const [errores, setErrores] = useState({});

  const validar = (nombre, valor) => {
    let error = '';
    if (!valor) {
      error = 'Este campo es obligatorio';
    } else if (nombre === 'email' && !valor.includes('@')) {
      error = 'Email inválido';
    } else if (nombre === 'password' && valor.length < 6) {
      error = 'Mínimo 6 caracteres';
    }
    return error;
  };

  const manejarCambio = (e) => {
    const { name, value } = e.target;
    setDatos({ ...datos, [name]: value });
    setErrores({ ...errores, [name]: validar(name, value) });
  };

  const manejarSubmit = (e) => {
    e.preventDefault();
    const nuevosErrores = {
      email: validar('email', datos.email),
      password: validar('password', datos.password)
    };
    setErrores(nuevosErrores);
    if (Object.values(nuevosErrores).every((e) => !e)) {
      console.log('Formulario válido, enviando:', datos);
    }
  };

  return (
    <form onSubmit={manejarSubmit} noValidate>
      <input
        name="email"
        value={datos.email}
        onChange={manejarCambio}
        placeholder="Email"
      />
      {errores.email && <p className="error">{errores.email}</p>}

      <input
        name="password"
        type="password"
        value={datos.password}
        onChange={manejarCambio}
        placeholder="Contraseña"
      />
      {errores.password && <p className="error">{errores.password}</p>}

      <button type="submit">Registrarse</button>
    </form>
  );
}

