function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    fetch(url)
      .then(res => res.json())
      .then(data => { setData(data); setLoading(false); });
  }, [url]);
  return { data, loading };
}

import { useEffect, useState } from 'react';

function ListaPost() {
  const [posts, setPosts] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let activo = true;   // evita setState tras desmontar

    const cargar = async () => {
      try {
        const res = await fetch('https://jsonplaceholder.typicode.com/posts');
        if (!res.ok) throw new Error('Error ' + res.status);
        const datos = await res.json();
        if (activo) setPosts(datos);
      } catch (e) {
        if (activo) setError(e.message);
      } finally {
        if (activo) setCargando(false);
      }
    };

    cargar();
    return () => { activo = false; };
  }, []);

  if (cargando) return <p>Cargando publicaciones...</p>;
  if (error) return <p className="error">Error: {error}</p>;

  return (
    <ul>
      {posts.map((post) => (
        <li key={post.id}>{post.title}</li>
      ))}
    </ul>
  );
}

import { useState } from 'react';

function CrearPost() {
  const [titulo, setTitulo] = useState('');
  const [enviando, setEnviando] = useState(false);
  const [respuesta, setRespuesta] = useState(null);

  const manejarSubmit = async (e) => {
    e.preventDefault();
    setEnviando(true);

    try {
      const res = await fetch('https://jsonplaceholder.typicode.com/posts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: titulo })
      });

      if (!res.ok) throw new Error('Error al crear');
      const nuevoPost = await res.json();
      setRespuesta('Creado con id: ' + nuevoPost.id);
      setTitulo('');
    } catch (error) {
      setRespuesta('Error: ' + error.message);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <form onSubmit={manejarSubmit}>
      <input
        value={titulo}
        onChange={(e) => setTitulo(e.target.value)}
        placeholder="Título del post"
      />
      <button type="submit" disabled={enviando || !titulo}>
        {enviando ? 'Enviando...' : 'Crear'}
      </button>
      {respuesta && <p>{respuesta}</p>}
    </form>
  );
}

import { useEffect, useState } from 'react';

// Hook reutilizable para consumir APIs
function useFetch(url) {
  const [datos, setDatos] = useState(null);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let activo = true;

    const cargar = async () => {
      setCargando(true);
      try {
        const res = await fetch(url);
        if (!res.ok) throw new Error('Error ' + res.status);
        const data = await res.json();
        if (activo) { setDatos(data); setError(null); }
      } catch (e) {
        if (activo) setError(e.message);
      } finally {
        if (activo) setCargando(false);
      }
    };

    cargar();
    return () => { activo = false; };
  }, [url]);   // re-carga cuando cambia la URL

  return { datos, cargando, error };
}

// Usarlo en cualquier componente
function Usuarios() {
  const { datos, cargando, error } =
    useFetch('https://jsonplaceholder.typicode.com/users');

  if (cargando) return <p>Cargando...</p>;
  if (error) return <p>Error: {error}</p>;

  return (
    <ul>
      {datos.map((u) => <li key={u.id}>{u.name}</li>)}
    </ul>
  );
}

